def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # If opponent defected on the first move, retaliate immediately.
    if history[0][1] == 'D':
        return 'D'

    opp_defects = sum(1 for a, b in history if b == 'D')

    # If opponent has never defected, exploit by defecting.
    if opp_defects == 0:
        return 'D'

    # Last round: defect to gain extra point.
    if n == 99:
        return 'D'

    # Otherwise, use the parent's logic.
    if n < 10:
        return 'C'

    my_defects = sum(1 for a, b in history if a == 'D')
    recent = history[-5:]
    recent_opp_defects = sum(1 for a, b in recent if b == 'D')
    recent_my_defects = sum(1 for a, b in recent if a == 'D')

    if opp_defects > n * 0.6:
        if recent_opp_defects == 5:
            return 'D'
        if n % 10 == 0:
            return 'C'
        return 'D'

    if opp_defects <= n * 0.15:
        if recent_opp_defects > 0 and recent_opp_defects <= 2:
            if recent_my_defects == 0:
                return 'D'
        return 'C'

    if len(history) >= 1:
        last_opp = history[-1][1]
        last_my = history[-1][0]

        if last_opp == 'D':
            if len(history) >= 2 and history[-2][1] == 'D':
                if recent_opp_defects >= 3:
                    return 'D'
                if rng.random() < 0.3:
                    return 'C'
                return 'D'
            return 'D'

        if last_my == 'D':
            return 'C'
        return 'C'

    return 'C'
